const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const s = await readline();

  let countX = 0;
  let countY = 0;

  let ans = 0;

  for (let c of s) {
    if (c == "X") {
      countX++;
    } else {
      countY++;
    }

    if (countX == countY) {
      ans++;
    }
  }

  console.log(ans);
})();

Java:
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String s = sc.nextLine();

    int countX = 0;
    int countY = 0;

    int ans = 0;

    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) == 'X') {
        countX++;
      } else {
        countY++;
      }

      if (countX == countY) {
        ans++;
      }
    }

    System.out.println(ans);
  }
}

C:
#include <stdio.h>

int main() {
    char s[10001];
    scanf("%s", s);

    int countX = 0;
    int countY = 0;

    int ans = 0;

    int i = 0;
    while (s[i] != '\0') {
        if (s[i] == 'X') {
            countX++;
        } else {
            countY++;
        }

        if (countX == countY) {
            ans++;
        }

        i++;
    }

    printf("%d\n", ans);

    return 0;
}
